    'Scan complete.' => 'Skanningen är klar.',
    'Scan cookies' => 'skanna cookies',
    'Scanning...' => 'Skannar…',
    'Scans browser cookies and infers expected cookies from tracking scripts on your site (even when blocked until consent). Known cookies are auto-mapped to categories.' => 'Skannar webbläsarens cookies och härleder förväntade cookies från spårningsskript på din webbplats (även när de blockeras tills samtycke ges). Kända cookies kopplas automatiskt till kategorier.',
    'Screen reader label of the × button.' => 'Skärmläsartext för ×-knappen.',
    'Script Blocking' => 'Skriptblockering',
    'Script Blocking tab' => 'Fliken Skriptblockering',
